/**
 * Arbitrary-precision shift/mask helpers that raise the same errors CPython
 * raises for `int` operands.
 */

import { PyMemoryError, PyValueError } from './errors.mjs';

function guardHuge(operation) {
  try {
    return operation();
  } catch (error) {
    // An allocation CPython would also refuse: it reports MemoryError.
    if (error instanceof RangeError) throw new PyMemoryError();
    throw error;
  }
}

/** `value << count`, raising `ValueError: negative shift count`. */
export function leftShift(value, count) {
  if (count < 0n) throw new PyValueError('negative shift count');
  return guardHuge(() => value << count);
}

/** `value >> count`, raising `ValueError: negative shift count`. */
export function rightShift(value, count) {
  if (count < 0n) throw new PyValueError('negative shift count');
  return guardHuge(() => value >> count);
}
